sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var push = {
    sam_request_id: 'ATF-SAM-0002',
    requested_for: 'atf-correlation-0002'
    // access_item and approval_authority deliberately omitted
  };
  var v = sam.validateInboundPush(push);
  if (v.ok) { stepResult.setFailed('validateInboundPush should refuse a push missing required fields'); return; }
  if (v.reason.indexOf('access_item') === -1 || v.reason.indexOf('approval_authority') === -1) {
    stepResult.setFailed('refusal reason should name every missing field, got: ' + v.reason);
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var push = {
    sam_request_id: 'ATF-SAM-0002',
    access_item: '   ',
    requested_for: 'atf-correlation-0002',
    approval_authority: 'app-owner'
  };
  var v = sam.validateInboundPush(push);
  if (v.ok) { stepResult.setFailed('a whitespace-only access_item should not satisfy the required-field check'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var v = sam.validateInboundPush(null);
  if (v.ok) { stepResult.setFailed('an empty push payload should never validate'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
